mapper.select:
select t.id, t.task_no, t.product_id, t.product_key, t.package_id, t.task_name, t.target_version, t.package_type, t.custom_type, t.module, t.rollout_mode, t.description, t.status, t.device_count, t.waiting_count, t.in_progress_count, t.success_count, t.failed_count, t.canceled_count, t.skipped_count, t.creator_id, t.tenant_id, t.strategy_json, t.create_time, t.update_time, t.start_time, t.finish_time, t.cancel_time, prod.name as product_name, p.package_name, p.version as package_version from iot_ota_task t left join iot_product prod on lower(prod.product_key) = lower(t.product_key) left join iot_ota_package p on p.id = t.package_id
and t.id = #{id}
and lower(t.task_no) like lower(concat('%', #{taskNo}, '%'))
and t.product_id = #{productId}
and lower(t.product_key) = lower(#{productKey})
and t.package_id = #{packageId}
and lower(t.task_name) like lower(concat('%', #{taskName}, '%'))
and lower(t.status) = lower(#{status})
and (t.tenant_id = #{tenantId} or ((t.tenant_id is null or t.tenant_id = '') and lower(t.creator_id) = lower(#{creatorId})))
and t.tenant_id = #{tenantId}
and lower(t.creator_id) = lower(#{creatorId})
order by t.create_time desc, t.id desc

mapper.update:
update iot_ota_task
task_no = #{taskNo}, product_id = #{productId}, product_key = #{productKey}, package_id = #{packageId}, task_name = #{taskName}, target_version = #{targetVersion}, package_type = #{packageType}, custom_type = #{customType}, module = #{module}, rollout_mode = #{rolloutMode}, description = #{description}, status = #{status}, device_count = #{deviceCount}, waiting_count = #{waitingCount}, in_progress_count = #{inProgressCount}, success_count = #{successCount}, failed_count = #{failedCount}, canceled_count = #{canceledCount}, skipped_count = #{skippedCount}, tenant_id = #{tenantId}, strategy_json = #{strategyJson}, start_time = #{startTime}, finish_time = #{finishTime}, cancel_time = #{cancelTime}, update_time = now()
where id = #{id}
